// AuthorizeMember is the resolver for the authorizeMember field.
func (r *mutationResolver) AuthorizeMember(ctx context.Context, requesterID string, groupID string, approve bool) (bool, error) {
	// 1. Extraer el Admin de forma segura (evita el panic)
	admin := utils.ForContext(ctx)
	if admin == nil {
		return false, fmt.Errorf("debe iniciar sesión para realizar esta acción")
	}

	// 2. Verificar que el grupo existe y quién es el admin real
	var dbAdminID string
	err := r.DB.QueryRow(ctx, "SELECT admin_id FROM groups WHERE id = $1", groupID).Scan(&dbAdminID)
	if err != nil {
		if err == pgx.ErrNoRows {
			return false, fmt.Errorf("el grupo especificado no existe")
		}
		return false, fmt.Errorf("error verificando permisos: %w", err)
	}

	// 3. Validar que el usuario actual es el dueño del grupo
	if dbAdminID != admin.ID {
		return false, fmt.Errorf("no tienes permisos de administrador en este grupo")
	}

	// 4. Iniciar Transacción para asegurar consistencia
	tx, err := r.DB.Begin(ctx)
	if err != nil {
		return false, err
	}
	defer tx.Rollback(ctx)

	if approve {
		// APROBAR: Cambiamos status a 'APPROVED'
		_, err = tx.Exec(ctx,
			"UPDATE group_members SET status = 'APPROVED' WHERE user_id = $1 AND group_id = $2",
			requesterID, groupID)
	} else {
		// RECHAZAR: Eliminamos la solicitud
		_, err = tx.Exec(ctx,
			"DELETE FROM group_members WHERE user_id = $1 AND group_id = $2",
			requesterID, groupID)
	}

	if err != nil {
		return false, fmt.Errorf("error al actualizar membresía: %w", err)
	}

	// 5. Limpiar la notificación correspondiente
	_, err = tx.Exec(ctx,
		"DELETE FROM notifications WHERE user_id = $1 AND requester_id = $2 AND group_id = $3",
		admin.ID, requesterID, groupID)

	// 6. Confirmar cambios
	err = tx.Commit(ctx)

	return err == nil, err
}

// CreateReminder is the resolver for the createReminder field.
func (r *mutationResolver) CreateReminder(ctx context.Context, title string, description *string, priority int32, completed *bool, dueDate string) (*model.Reminder, error) {
	// 1. Obtener el usuario del contexto
	user := utils.ForContext(ctx)
	if user == nil {
		return nil, fmt.Errorf("no autorizado")
	}

	// 2. BUSCAR EL GROUP_ID del usuario (Lógica Bento)
	// Asumimos que el usuario pertenece a un grupo activo
	var groupID string
	err := r.DB.QueryRow(ctx, `
        SELECT group_id FROM group_members 
        WHERE user_id = $1 AND (status = 'APPROVED' OR status = 'ADMIN') 
        LIMIT 1
    `, user.ID).Scan(&groupID)

	if err != nil {
		if err == pgx.ErrNoRows {
			return nil, fmt.Errorf("debes pertenecer a un grupo aprobado para crear recordatorios")
		}
		return nil, fmt.Errorf("error al verificar membresía: %v", err)
	}

	// 3. Procesar fecha
	parsedTime, err := time.Parse(time.RFC3339, dueDate)
	if err != nil {
		parsedTime = time.Now()
	}

	var rem models.Reminder
	isCompleted := false
	if completed != nil {
		isCompleted = *completed
	}

	// 4. INSERTAR INCLUYENDO EL GROUP_ID
	err = r.DB.QueryRow(ctx, `
        INSERT INTO reminders (user_id, group_id, title, description, due_date, priority, is_completed)
        VALUES ($1, $2, $3, $4, $5, $6, $7)
        RETURNING id, title, description, due_date::TEXT, is_completed, priority
    `, user.ID, groupID, title, description, parsedTime, priority, isCompleted).Scan(
		&rem.ID, &rem.Title, &rem.Description, &rem.ID, &rem.IsCompleted, &rem.Priority, // Nota: scan a rem.ID temporal para la fecha
	)

	if err != nil {
		return nil, fmt.Errorf("error al insertar en DB: %v", err)
	}

	return &model.Reminder{
		ID:          rem.ID,
		Title:       rem.Title,
		Description: rem.Description,
		DueDate:     dueDate,
		IsCompleted: rem.IsCompleted,
		Priority:    rem.Priority,
	}, nil
}

// ToggleReminder is the resolver for the toggleReminder field.
func (r *mutationResolver) ToggleReminder(ctx context.Context, id string) (*model.Reminder, error) {
	user := utils.ForContext(ctx)
	if user == nil {
		return nil, fmt.Errorf("no autorizado")
	}

	var reminder models.Reminder

	err := r.DB.QueryRow(ctx, `SELECT id, is_completed FROM reminders 
                        WHERE id=$1
                        AND user_id=$2`, id, user.ID).Scan(
		&reminder.ID, &reminder.IsCompleted)
	if err != nil {
		if err == pgx.ErrNoRows {
			return nil, fmt.Errorf("credenciales inválidas")
		}
		return nil, fmt.Errorf("error no existe reminder: %w", err)
	}

	err = r.DB.QueryRow(ctx, `
		UPDATE reminders 
		SET is_completed = $1 
		WHERE id = $2 
		AND user_id=$3
		RETURNING id, is_completed
	`, !reminder.IsCompleted, id, user.ID).Scan(&reminder.ID, &reminder.IsCompleted)
	if err != nil {
		return nil, fmt.Errorf("error no actualizo reminder: %w", err)
	}

	return &model.Reminder{
		ID:          reminder.ID,
		IsCompleted: reminder.IsCompleted,
	}, nil
}

