// ApproveMember is the resolver for the approveMember field.
func (r *mutationResolver) ApproveMember(ctx context.Context, userID string) (bool, error) {
	admin := utils.ForContext(ctx)
	if admin == nil {
		return false, fmt.Errorf("no autorizado")
	}

	// 1. Ejecutar el UPDATE con validación de privilegios
	// Verificamos que el que ejecuta (admin.ID) sea realmente el ADMIN del grupo
	// al que pertenece el usuario a aprobar.
	result, err := r.DB.Exec(ctx, `
		UPDATE group_members 
		SET status = 'APPROVED' 
		WHERE user_id = $1 
		AND group_id IN (SELECT id FROM groups WHERE admin_id = $2)
		AND status = 'PENDING'
	`, userID, admin.ID)

	if err != nil {
		return false, fmt.Errorf("error al aprobar miembro: %w", err)
	}

	// 2. Verificar si se actualizó algo
	if result.RowsAffected() == 0 {
		return false, fmt.Errorf("no tienes permisos o el usuario no está pendiente")
	}

	log.Printf("Admin %s aprobó al usuario %s", admin.Email, userID)
	return true, nil
}

// PendingMembers is the resolver for the pendingMembers field.
// CAMBIA EL RECEPTOR: de (r *queryResolver) a (r *mutationResolver)
func (r *mutationResolver) PendingMembers(ctx context.Context) ([]*model.User, error) {
	admin := utils.ForContext(ctx)
	if admin == nil {
		return nil, fmt.Errorf("no autorizado")
	}

	// El resto de la lógica de la base de datos se queda igual...
	rows, err := r.DB.Query(ctx, `
        SELECT u.id, u.first_name, u.last_name, u.email 
        FROM users u
        JOIN group_members gm ON u.id = gm.user_id
        JOIN groups g ON gm.group_id = g.id
        WHERE g.admin_id = $1 AND gm.status = 'PENDING'
    `, admin.ID)

	if err != nil {
		return nil, err
	}
	defer rows.Close()

	var members []*model.User
	for rows.Next() {
		var u model.User
		// Mapeamos a model.User (el tipo de GraphQL)
		if err := rows.Scan(&u.ID, &u.FirstName, &u.LastName, &u.Email); err != nil {
			return nil, err
		}
		members = append(members, &u)
	}

	return members, nil
}

// UpdateReminder is the resolver for the updateReminder field.
// Cambia 'priority int' por 'priority int32' en esta línea:
func (r *mutationResolver) UpdateReminder(ctx context.Context, id string, title string, description *string, priority int32, completed *bool, dueDate string) (*model.Reminder, error) {
	// 1. Añadimos ::TEXT al final de due_date en el RETURNING
	query := `
		UPDATE reminders 
		SET title = $1, description = $2, priority = $3, is_completed = $4, due_date = $5 
		WHERE id = $6
		RETURNING id, title, description, priority, is_completed, due_date::TEXT
	`

	var updatedReminder model.Reminder

	isComp := false
	if completed != nil {
		isComp = *completed
	}

	// 2. Ahora el Scan funcionará porque Postgres entrega un string
	err := r.DB.QueryRow(ctx, query, title, description, priority, isComp, dueDate, id).Scan(
		&updatedReminder.ID,
		&updatedReminder.Title,
		&updatedReminder.Description,
		&updatedReminder.Priority,
		&updatedReminder.IsCompleted,
		&updatedReminder.DueDate, // Ya puede recibirlo como string
	)

	if err != nil {
		return nil, fmt.Errorf("error al actualizar el recordatorio: %v", err)
	}

	return &updatedReminder, nil
}

