// Notifications is the resolver for the notifications field.
func (r *queryResolver) Notifications(ctx context.Context) ([]*model.Notification, error) {
	// 1. EXTRAER EL USUARIO DE FORMA SEGURA (Como haces en 'Me')
	user := utils.ForContext(ctx)
	if user == nil {
		return nil, fmt.Errorf("debe iniciar sesión para ver notificaciones")
	}

	// 2. Query usando user.ID
	query := `
        SELECT id, type, title, message, is_read, created_at::TEXT, requester_id::TEXT, group_id::TEXT 
        FROM notifications 
        WHERE user_id = $1 
        ORDER BY created_at DESC
    `

	rows, err := r.DB.Query(ctx, query, user.ID) // Usamos user.ID aquí
	if err != nil {
		return nil, fmt.Errorf("error en base de datos: %v", err)
	}
	defer rows.Close()

	var notifications []*model.Notification
	for rows.Next() {
		var n model.Notification

		// 3. SCAN SEGURO: Usamos variables temporales para campos que pueden ser NULL
		var reqID, grpID *string // Punteros para manejar NULL de la DB

		err := rows.Scan(
			&n.ID,
			&n.Type,
			&n.Title,
			&n.Message,
			&n.IsRead,
			&n.CreatedAt,
			&reqID, // Escaneamos a puntero
			&grpID, // Escaneamos a puntero
		)
		if err != nil {
			log.Printf("Error escaneando notificación: %v", err)
			continue
		}

		n.RequesterID = reqID
		n.GroupID = grpID

		notifications = append(notifications, &n)
	}

	return notifications, nil
}

// MyReminders is the resolver for the myReminders field.
func (r *queryResolver) MyReminders(ctx context.Context) ([]*model.Reminder, error) {
	user := utils.ForContext(ctx)
	if user == nil {
		return nil, fmt.Errorf("no autorizado")
	}

	var groupID string
	// PASO 1: Buscar si el usuario tiene un grupo donde ya esté aprobado o sea ADMIN
	err := r.DB.QueryRow(ctx, `
        SELECT group_id FROM group_members 
        WHERE user_id = $1 AND status IN ('ADMIN', 'APPROVED') 
        LIMIT 1
    `, user.ID).Scan(&groupID)

	var query string
	var args []interface{}

	if err == nil && groupID != "" {
		// PASO 2 (CASO A): El usuario es miembro activo de un grupo.
		// Traemos TODOS los recordatorios del grupo.
		log.Printf("🚀 Usuario %s tiene acceso al grupo %s. Cargando recordatorios grupales.", user.Email, groupID)
		query = `
            SELECT id, title, description, due_date::TEXT, is_completed, priority 
            FROM reminders 
            WHERE group_id = $1
            ORDER BY due_date ASC
       `
		args = append(args, groupID)
	} else {
		// PASO 2 (CASO B): No tiene grupo o aún no lo aprueban.
		// Solo traemos sus recordatorios personales.
		log.Printf("🔒 Usuario %s en modo privado. Cargando recordatorios personales.", user.Email)
		query = `
            SELECT id, title, description, due_date::TEXT, is_completed, priority 
            FROM reminders 
            WHERE user_id = $1
            ORDER BY due_date ASC
       `
		args = append(args, user.ID)
	}

	// Ejecutar la consulta final
	rows, err := r.DB.Query(ctx, query, args...)
	if err != nil {
		return nil, fmt.Errorf("error al consultar recordatorios: %v", err)
	}
	defer rows.Close()

	var reminders []*model.Reminder
	for rows.Next() {
		// Usamos un struct temporal para manejar el scan de forma segura
		var rem struct {
			ID          string
			Title       string
			Description *string
			DueDate     string
			IsCompleted bool
			Priority    int32
		}

		if err := rows.Scan(&rem.ID, &rem.Title, &rem.Description, &rem.DueDate, &rem.IsCompleted, &rem.Priority); err != nil {
			log.Printf("❌ Error escaneando recordatorio: %v", err)
			continue
		}

		reminders = append(reminders, &model.Reminder{
			ID:          rem.ID,
			Title:       rem.Title,
			Description: rem.Description,
			DueDate:     rem.DueDate,
			IsCompleted: rem.IsCompleted,
			Priority:    rem.Priority,
		})
	}

	return reminders, nil
}

// NotificationAdded is the resolver for the notificationAdded field.
func (r *subscriptionResolver) NotificationAdded(ctx context.Context) (<-chan *model.Notification, error) {
	userID := ctx.Value("userID").(string)
	// Retornamos el canal del broker para este usuario
	return r.Broker.Subscribe(userID), nil
}

// Mutation returns MutationResolver implementation.
func (r *Resolver) Mutation() MutationResolver { return &mutationResolver{r} }

// Query returns QueryResolver implementation.
func (r *Resolver) Query() QueryResolver { return &queryResolver{r} }

// Subscription returns SubscriptionResolver implementation.
func (r *Resolver) Subscription() SubscriptionResolver { return &subscriptionResolver{r} }

type mutationResolver struct{ *Resolver }
type queryResolver struct{ *Resolver }
type subscriptionResolver struct{ *Resolver }
